import { useState, useEffect } from "react";
import { View, Text, Pressable } from "react-native";

// Giao diện giống AsyncStorage: getItem/setItem BẤT ĐỒNG BỘ, chỉ lưu CHUỖI
const makeMemoryStorage = () => {
  const m = {};
  return {
    getItem: async (k) => (k in m ? m[k] : null),
    setItem: async (k, v) => { m[k] = v; },
  };
};
const storage = makeMemoryStorage();

function useStoredState(key, initial) {
  const [value, setValue] = useState(initial);
  const [ready, setReady] = useState(false);
  useEffect(() => {
    storage.getItem(key).then((raw) => {
      if (raw !== null) { try { setValue(JSON.parse(raw)); } catch {} }   // dữ liệu hỏng -> dùng mặc định
      setReady(true);
    });
  }, [key]);
  useEffect(() => { if (ready) storage.setItem(key, JSON.stringify(value)); }, [key, value, ready]);
  return [value, setValue, ready];
}

export default function App() {
  const [count, setCount, ready] = useStoredState("count", 0);
  if (!ready) return <Text>Đang đọc…</Text>;
  return <View><Text testID="n">{count}</Text><Pressable testID="inc" onPress={() => setCount(count + 1)}><Text>+1</Text></Pressable></View>;
}

