import { useState, useEffect } from "react";
import { Text } from "react-native";

const m = {};
const storage = {
  getItem: async (k) => (k in m ? m[k] : null),
  setItem: async (k, v) => { m[k] = v; },
};

async function save(key, obj) {
  await storage.setItem(key, JSON.stringify(obj));
}
async function load(key, fallback) {
  const raw = await storage.getItem(key);
  try { return raw === null ? fallback : JSON.parse(raw); } catch { return fallback; }
}

export default function App() {
  const [r, setR] = useState("");
  useEffect(() => {
    (async () => {
      const a = await load("a", "F");
      await save("a", { x: 1 });
      const b = (await load("a", "F")).x;
      setR(a + "|" + b);
    })();
  }, []);
  return <Text testID="r">{r}</Text>;
}

